import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.BPyF_sP4.js";const b=JSON.parse('{"title":"AI Agent Handbook","description":"","frontmatter":{"title":"AI Agent Handbook","bookSource":"README.md","readingMinutes":12,"prev":false,"next":false,"editLink":true},"headers":[],"relativePath":"about.md","filePath":"README.md","lastUpdated":1791889397000}'),n={name:"about.md"};function o(h,t,i,l,g,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="ai-agent-handbook" tabindex="-1">AI Agent Handbook <a class="header-anchor" href="#ai-agent-handbook" aria-label="Permalink to &quot;AI Agent Handbook&quot;">​</a></h1><p>中文 | <a href="/ai-agent-handbook/en/">English</a></p><p>按照 Agent 的架构、构建、运行、治理和调优应用生命周期，总结了我们在企业级 Agent 落地过程中的实践经验和体会，若白皮书能对个人学习和企业落地 Agent 起到一点点的促进作用，将是我们莫大的荣幸。</p><p>谨以此项目，献给参与 AI 建设的所有同行者们。</p><p><a href="https://aliyun.github.io/ai-agent-handbook/" target="_blank" rel="noreferrer">在线阅读</a> · <a href="https://aliyun.github.io/ai-agent-handbook/contents.html" target="_blank" rel="noreferrer">全书目录</a> · <a href="https://aliyun.github.io/ai-agent-handbook/reading-guide.html" target="_blank" rel="noreferrer">阅读指南</a></p><p>阅读站提供章节导航、中文搜索、图表与图片放大、明暗主题和阅读位置记忆。本地预览可使用 Node.js 22 执行 <code>npm ci</code>、<code>npm run dev</code>；站点维护与 GitHub Pages 发布方法见<a href="https://github.com/aliyun/ai-agent-handbook/blob/main/WEBSITE.md" target="_blank" rel="noreferrer">维护说明</a>。</p><hr><h2 id="_1-白皮书架构与写作背景" tabindex="-1">1. 白皮书架构与写作背景 <a class="header-anchor" href="#_1-白皮书架构与写作背景" aria-label="Permalink to &quot;1. 白皮书架构与写作背景&quot;">​</a></h2><p>2025年9月，我们发布了<a href="https://developer.aliyun.com/ebook/8479" target="_blank" rel="noreferrer">《AI 原生应用架构白皮书》</a>，围绕 AI 原生应用的 DevOps 全生命周期，从架构设计、技术选型、工程实践到运维优化，对概念和重难点进行体系化的拆解，并尝试提供一些解题思路。但随着模型和智能体技术的快速发展，我们发现，市场的关注度已经从快速构建智能体，转向以下三大新挑战：</p><ul><li><p>工程化挑战：从概率智能到可靠生产力，Agent 能够承担关键任务。</p></li><li><p>规模化挑战：稳定、安全、性能、成本，从单点试验到智能基础设施，Agent 能够被大规模部署。</p></li><li><p>组织化挑战：从 Agent 孤岛到智能组织，Agent 能够进入核心业务流程。</p></li></ul><p>去年的那本白皮书，显然难以应对这些新的诉求。</p><p>因此，我们重新梳理了白皮书的架构，希望通过更与时俱进的内容，更高的实践篇幅占比，以及更社区化的协作，为企业选型和内部立项提供参考，并通过开源的方式长期维护该白皮书，持续呈现 AI 原生应用架构的前沿思考和落地实践。</p><h2 id="_2-目标读者与收获" tabindex="-1">2. 目标读者与收获 <a class="header-anchor" href="#_2-目标读者与收获" aria-label="Permalink to &quot;2. 目标读者与收获&quot;">​</a></h2><p>本白皮书主要面向企业级 Agent 构建与落地场景。它既适合关注 Agent 开发的工程人员，也适合用于企业内部的技术选型、架构评审、项目立项和跨团队共识建设。</p><table tabindex="0"><thead><tr><th>读者</th><th>建议关注</th><th>你将获得</th></tr></thead><tbody><tr><td>Agent / AI 应用开发者</td><td>构建篇、运行篇、调优篇</td><td>掌握 Harness、上下文、状态、工具、沙箱、轨迹与评估闭环等核心工程方法。</td></tr><tr><td>架构师与平台工程师</td><td>架构篇、运行篇、治理篇</td><td>建立从组件、平台责任到生命周期的完整架构视图，形成可扩展的 Agent 基础设施设计。</td></tr><tr><td>技术负责人和研发管理者</td><td>架构篇、治理篇、实践篇</td><td>判断应用形态、成熟度、投入边界与生产风险，支撑选型、立项和组织协同。</td></tr><tr><td>产品与业务负责人</td><td>调研报告、架构篇、实践篇</td><td>理解适合 Agent 的任务、人与 Agent 的责任边界，以及从试点走向核心流程的条件。</td></tr><tr><td>安全、质量与运维人员</td><td>运行篇、治理篇、调优篇</td><td>建立可观测、审计、安全授权、上线验证、持续评估和故障归因机制。</td></tr><tr><td>研究者与生态贡献者</td><td>全书与实践篇</td><td>了解企业一线问题、工程抽象和开放议题，并参与共同完善行业知识体系。</td></tr></tbody></table><p>完整阅读后，你将能够：</p><ul><li>从业务目标、任务确定性和风险出发，选择最低充分的 Agent 架构；</li><li>理解 Model 与 Harness 的责任边界，不把所有问题都归因于模型能力；</li><li>设计可持续推进、可中断恢复、可验证完成的 Agent 任务系统；</li><li>为 Agent 建立执行环境、状态、流量、权限、观测与成本治理底座；</li><li>用 Trace、Trajectory、黄金数据集和评估实验形成持续改进的数据飞轮；</li><li>将方法映射到研发效能、设计、运维、企业 IT、客户运营等实际场景。</li></ul><h2 id="_3-阅读导引" tabindex="-1">3. 阅读导引 <a class="header-anchor" href="#_3-阅读导引" aria-label="Permalink to &quot;3. 阅读导引&quot;">​</a></h2><h3 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to &quot;目录结构&quot;">​</a></h3><table tabindex="0"><thead><tr><th>篇章</th><th>目录</th><th>章节范围</th><th>阅读重点</th></tr></thead><tbody><tr><td><a href="/ai-agent-handbook/survey.html">2026 Agent 开发者调研报告</a></td><td>根目录</td><td>—</td><td>企业 Agent 开发、生产化、架构选型、工具链、治理与评估现状。</td></tr><tr><td><a href="/ai-agent-handbook/preface.html">前言</a></td><td><code>00-preface/</code></td><td>—</td><td>白皮书结构和背景。</td></tr><tr><td><a href="/ai-agent-handbook/architecture/">架构篇</a></td><td><code>01-architecture/</code></td><td>第 1–2 章</td><td>定义对象、判断形态、选择成熟度并建立参考架构。</td></tr><tr><td><a href="/ai-agent-handbook/build/">构建篇</a></td><td><code>02-build/</code></td><td>第 3–6 章</td><td>以 Harness 为核心，组织任务、信息和行动。</td></tr><tr><td><a href="/ai-agent-handbook/run/">运行篇</a></td><td><code>03-run/</code></td><td>第 7–12 章</td><td>从单 Agent 稳定运行扩展到异步、多 Agent 与分布式通信。</td></tr><tr><td><a href="/ai-agent-handbook/governance/">治理篇</a></td><td><code>04-governance/</code></td><td>第 13–16 章</td><td>让运行可见、行为有边界、资产可管理、上线前可验证。</td></tr><tr><td><a href="/ai-agent-handbook/optimization/">调优篇</a></td><td><code>05-optimization/</code></td><td>第 17–24 章</td><td>从模型与 Agent 两条主线构建持续优化闭环。</td></tr><tr><td><a href="/ai-agent-handbook/cases/">实践篇</a></td><td><code>06-case-study/</code></td><td>第 25–29 章、Jev 专题</td><td>企业实践、垂直场景、Agent Infra 前沿探索与结构化决策。</td></tr><tr><td><a href="/ai-agent-handbook/outlook/">总结与展望篇</a></td><td><code>07-conclusion/</code></td><td>第 30 章</td><td>从 Agentic Application 走向 Agentic OS。</td></tr></tbody></table><h3 id="章节导航" tabindex="-1">章节导航 <a class="header-anchor" href="#章节导航" aria-label="Permalink to &quot;章节导航&quot;">​</a></h3><table tabindex="0"><thead><tr><th>篇章</th><th>章节</th><th>核心内容</th></tr></thead><tbody><tr><td>架构篇</td><td><a href="/ai-agent-handbook/architecture/chapter-01.html">第 1 章　AI 原生应用的新阶段</a></td><td>应用形态演进、Agentic Application 的定义与边界、企业成熟度判断。</td></tr><tr><td>架构篇</td><td><a href="/ai-agent-handbook/architecture/chapter-02.html">第 2 章　Agentic Application 参考架构</a></td><td>组件视图、平台责任与生命周期视图，以及从决策到运行和改进的架构落位。</td></tr><tr><td>构建篇</td><td><a href="/ai-agent-handbook/build/chapter-03.html">第 3 章　范式：Harness 的主流构建方式和责任边界</a></td><td>高代码框架、产品化 Harness、Managed Agents、Agent 云产品与平台责任。</td></tr><tr><td>构建篇</td><td><a href="/ai-agent-handbook/build/chapter-04.html">第 4 章　任务：编排、长程推进与协作流转</a></td><td>Agent Loop、任务状态机、计划、阶段门禁、委派、异步续行与完成证据。</td></tr><tr><td>构建篇</td><td><a href="/ai-agent-handbook/build/chapter-05.html">第 5 章　信息：上下文、状态与可复用能力资产</a></td><td>Context Builder、压缩与卸载、Session、Task State、Workspace、Memory、Knowledge 与 Skill。</td></tr><tr><td>构建篇</td><td><a href="/ai-agent-handbook/build/chapter-06.html">第 6 章　行动：受控执行、验证反馈与交付准备</a></td><td>Action Plane、Function Calling、MCP、A2A、环境契约、权限、HITL 与验证闭环。</td></tr><tr><td>运行篇</td><td><a href="/ai-agent-handbook/run/chapter-07.html">第 7 章　Agent 运行时与沙箱</a></td><td>沙箱、Agent Runtime、工作空间、环境生命周期与生产运行条件。</td></tr><tr><td>运行篇</td><td><a href="/ai-agent-handbook/run/chapter-08.html">第 8 章　Agent 状态存储与语义资产</a></td><td>Event Log、Checkpoint、工作区快照、Artifact、长期记忆、RAG 与业务语义。</td></tr><tr><td>运行篇</td><td><a href="/ai-agent-handbook/run/chapter-09.html">第 9 章　AI 网关与统一流量治理</a></td><td>LLM、MCP、Agent 三类流量的身份、权限、预算、路由、审计与审批。</td></tr><tr><td>运行篇</td><td><a href="/ai-agent-handbook/run/chapter-10.html">第 10 章　Agent 异步任务与自动化流程</a></td><td>同步与异步边界、任务完成语义、定时任务、长时任务与自动化工作流。</td></tr><tr><td>运行篇</td><td><a href="/ai-agent-handbook/run/chapter-11.html">第 11 章　Multi-Agent 协作与编排</a></td><td>异构 Agent 接入、团队拓扑、任务分派、结果聚合与编排职责。</td></tr><tr><td>运行篇</td><td><a href="/ai-agent-handbook/run/chapter-12.html">第 12 章　Agent 分布式通信</a></td><td>能力面、协作面、内构面和人机面的通信协议与消息治理。</td></tr><tr><td>治理篇</td><td><a href="/ai-agent-handbook/governance/chapter-13.html">第 13 章　Agent 的可观测性</a></td><td>指标、日志、Trace、事件、成本归因与审计。</td></tr><tr><td>治理篇</td><td><a href="/ai-agent-handbook/governance/chapter-14.html">第 14 章　Agent 安全</a></td><td>Prompt Injection、身份鉴权、逐次校验、高危授权与数据出域防护。</td></tr><tr><td>治理篇</td><td><a href="/ai-agent-handbook/governance/chapter-15.html">第 15 章　AI 资产的发现与管理</a></td><td>Prompt、Skill、MCP 与 Agent 的注册、版本、发现、依赖和发布管理。</td></tr><tr><td>治理篇</td><td><a href="/ai-agent-handbook/governance/chapter-16.html">第 16 章　Agent 行为生成与质量验证</a></td><td>用户模拟、环境模拟、场景配置与上线前的 Agent Simulation。</td></tr><tr><td>调优篇</td><td><a href="/ai-agent-handbook/optimization/chapter-17.html">第 17 章　模型调优</a></td><td>模型问题的归因判据、SFT、Agentic RL、模型蒸馏与上线验收。</td></tr><tr><td>调优篇</td><td><a href="/ai-agent-handbook/optimization/chapter-18.html">第 18 章　Agent 调优总览</a></td><td>Agent 调优对象、方法边界与数据飞轮全景。</td></tr><tr><td>调优篇</td><td><a href="/ai-agent-handbook/optimization/chapter-19.html">第 19 章　Agent 轨迹数据</a></td><td>从 Trace 到 Trajectory，组织可复用的行为与决策证据。</td></tr><tr><td>调优篇</td><td><a href="/ai-agent-handbook/optimization/chapter-20.html">第 20 章　Agent 运行时数据处理</a></td><td>运行数据采集、清洗、加工与声明式数据 Pipeline。</td></tr><tr><td>调优篇</td><td><a href="/ai-agent-handbook/optimization/chapter-21.html">第 21 章　Agent 黄金数据集</a></td><td>构建带输入、轨迹、结果与判据的高质量评估数据资产。</td></tr><tr><td>调优篇</td><td><a href="/ai-agent-handbook/optimization/chapter-22.html">第 22 章　Agent 优化：Badcase</a></td><td>Badcase 发现、归因、修复、回归与实验验证。</td></tr><tr><td>调优篇</td><td><a href="/ai-agent-handbook/optimization/chapter-23.html">第 23 章　受控自进化</a></td><td>把有效经验转化为 Memory、Skill、工具和运行机制，并控制自进化风险。</td></tr><tr><td>调优篇</td><td><a href="/ai-agent-handbook/optimization/chapter-24.html">第 24 章　Agent 边缘运行时与全球优化</a></td><td>边缘运行时、边缘评估、性能成本、内容分发、安全与仿真。</td></tr><tr><td>实践篇</td><td><a href="/ai-agent-handbook/cases/chapter-25/">第 25 章　研发效能</a></td><td>代码审查、缺陷检测、补丁交付、研发协作与端到端交付实践。</td></tr><tr><td>实践篇</td><td><a href="/ai-agent-handbook/cases/chapter-26/">第 26 章　设计工程</a></td><td>Vibe Designing 与 GenUI 的设计范式和工程实践。</td></tr><tr><td>实践篇</td><td><a href="/ai-agent-handbook/cases/chapter-27/">第 27 章　运维、安全与企业 IT</a></td><td>汽车、连锁零售和企业软件的大规模智能运维实践。</td></tr><tr><td>实践篇</td><td><a href="/ai-agent-handbook/cases/chapter-28/">第 28 章　客户、销售与运营</a></td><td>长周期记忆、内容洞察、办公提效和 Data Agent 实践。</td></tr><tr><td>实践篇</td><td><a href="/ai-agent-handbook/cases/chapter-29.html">第 29 章　GOAI Agent Infra 赛道：多 Agent 协同的前沿实践探索</a></td><td>世界人工智能开源大赛优秀作品与多领域 Agent Infra 探索。</td></tr><tr><td>实践篇</td><td><a href="/ai-agent-handbook/cases/jev/">Jev 专题：结构化决策的实践</a></td><td>Jev 的模型解析、接口示例与可复用的决策模式。</td></tr><tr><td>总结与展望篇</td><td><a href="/ai-agent-handbook/outlook/chapter-30.html">第 30 章　从 Agentic Application 到 Agentic OS</a></td><td>从单个应用走向可协作、可治理、可持续演进的智能系统。</td></tr></tbody></table><h3 id="实践案例导航" tabindex="-1">实践案例导航 <a class="header-anchor" href="#实践案例导航" aria-label="Permalink to &quot;实践案例导航&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th>案例</th></tr></thead><tbody><tr><td>第 25 章　研发效能</td><td><a href="/ai-agent-handbook/cases/chapter-25/abaci.html">ABACI 内核补丁定向测试与缺陷检测智能体</a></td></tr><tr><td>第 25 章　研发效能</td><td><a href="/ai-agent-handbook/cases/chapter-25/kitta.html">Kitta：领域专用 Code Review Agent</a></td></tr><tr><td>第 25 章　研发效能</td><td><a href="/ai-agent-handbook/cases/chapter-25/patchpilot.html">PatchPilot Agents：让内核补丁交付成为可编排、可验证的工程闭环</a></td></tr><tr><td>第 25 章　研发效能</td><td><a href="/ai-agent-handbook/cases/chapter-25/polardb-x.html">从报警到自动修复，PolarDB-X 的 Loop 工程实践</a></td></tr><tr><td>第 25 章　研发效能</td><td><a href="/ai-agent-handbook/cases/chapter-25/cloud-communications.html">从编码提效到端到端交付，云通信的人机协作实践</a></td></tr><tr><td>第 25 章　研发效能</td><td><a href="/ai-agent-handbook/cases/chapter-25/security-engineering.html">从评测驱动到端到端交付：AI Agent 安全产品研发提效实践</a></td></tr><tr><td>第 25 章　研发效能</td><td><a href="/ai-agent-handbook/cases/chapter-25/engineering-team.html">多 Agent 组成研发小队：AI 研发如何从写代码走向端到端交付</a></td></tr><tr><td>第 26 章　设计工程</td><td><a href="/ai-agent-handbook/cases/chapter-26/genui.html">GenUI：让 Agent 从给出答案走向交付结果</a></td></tr><tr><td>第 26 章　设计工程</td><td><a href="/ai-agent-handbook/cases/chapter-26/vibe-designing.html">Vibe Designing：意图驱动的AI设计范式进化</a></td></tr><tr><td>第 27 章　运维、安全与企业 IT</td><td><a href="/ai-agent-handbook/cases/chapter-27/geely.html">吉利汽车智能运维的落地实践</a></td></tr><tr><td>第 27 章　运维、安全与企业 IT</td><td><a href="/ai-agent-handbook/cases/chapter-27/tastien.html">塔斯汀万店连锁的智能运维闭环实践</a></td></tr><tr><td>第 27 章　运维、安全与企业 IT</td><td><a href="/ai-agent-handbook/cases/chapter-27/chanjet.html">畅捷通的可观测与智能运维实践</a></td></tr><tr><td>第 28 章　客户、销售与运营</td><td><a href="/ai-agent-handbook/cases/chapter-28/minimax.html">MiniMax 构建海量长周期记忆数据底座的实践</a></td></tr><tr><td>第 28 章　客户、销售与运营</td><td><a href="/ai-agent-handbook/cases/chapter-28/shinewing.html">会计师事务所信永中和的办公提效探索</a></td></tr><tr><td>第 28 章　客户、销售与运营</td><td><a href="/ai-agent-handbook/cases/chapter-28/bilibili.html">哔哩哔哩构建全域内容洞察的实践</a></td></tr><tr><td>第 28 章　客户、销售与运营</td><td><a href="/ai-agent-handbook/cases/chapter-28/data-agent.html">运营分析 Data Agent 实践</a></td></tr><tr><td>Jev 专题</td><td><a href="/ai-agent-handbook/cases/jev/deep-dive.html">深度解析 Jev 模型：如何快速做结构化决策</a></td></tr><tr><td>Jev 专题</td><td><a href="/ai-agent-handbook/cases/jev/hiroute.html">HiRoute：Jev 模型智能路由实践</a></td></tr></tbody></table><h3 id="推荐阅读路径" tabindex="-1">推荐阅读路径 <a class="header-anchor" href="#推荐阅读路径" aria-label="Permalink to &quot;推荐阅读路径&quot;">​</a></h3><ul><li><strong>第一次系统了解企业 Agent</strong>：调研报告 → 第 1–2 章 → 第 3–6 章 → 第 13–16 章。</li><li><strong>正在把 Agent 接入生产</strong>：第 7–9 章 → 第 13–14 章 → 第 18–23 章。</li><li><strong>正在建设多 Agent 系统</strong>：第 4–6 章 → 第 10–12 章 → 第 13、16 章。</li><li><strong>负责评估与持续优化</strong>：第 13 章 → 第 18–23 章 → 对应领域实践案例。</li><li><strong>负责选型或项目立项</strong>：调研报告 → 第 1–3 章 → 实践篇 → 第 30 章。</li></ul><h2 id="_4-下一步规划" tabindex="-1">4. 下一步规划 <a class="header-anchor" href="#_4-下一步规划" aria-label="Permalink to &quot;4. 下一步规划&quot;">​</a></h2><p>白皮书将以开放项目的方式持续维护，而不是在首次发布后封存。接下来的重点包括：</p><ul><li><strong>扩展企业实践案例</strong>：增加更多来自研发、运营、客服、数据、安全、财务和行业场景的一线案例，补充成功路径、架构取舍与真实失败模式。</li><li><strong>增加云资源线上体验</strong>：围绕沙箱、Runtime、AI 网关、状态存储、可观测和评估等关键能力，设计可复现的云上体验流程，让读者从阅读进一步走向动手验证。</li><li><strong>持续完善治理内容</strong>：跟进身份权限、Prompt Injection 防护、数据出域、审计、资产注册、版本治理和上线前仿真等企业核心议题。</li><li><strong>持续完善评估体系</strong>：补充任务成功率、轨迹评估、LLM-as-Judge、黄金数据集、Badcase 回归、线上实验和成本质量权衡等方法与案例。</li><li><strong>跟进技术演进</strong>：持续吸收模型、Harness、协议、Runtime、多 Agent 和 Agentic OS 的新进展，并及时修正已经不再适用的判断。</li><li><strong>建设社区协作机制</strong>：逐步完善内容规范、案例模板、术语表、校对流程和版本发布方式，降低高质量贡献的门槛。</li></ul><h3 id="欢迎贡献" tabindex="-1">欢迎贡献 <a class="header-anchor" href="#欢迎贡献" aria-label="Permalink to &quot;欢迎贡献&quot;">​</a></h3><p>欢迎开发者、架构师、研究者、企业技术团队和产品实践者参与共建。你可以：</p><ul><li>提交 Issue，指出事实错误、概念歧义、链接失效或需要补充的主题；</li><li>提交 Pull Request，完善章节、修正内容、优化图表或补充参考资料；</li><li>分享经过脱敏的企业实践、故障复盘、评估方法与架构取舍；</li><li>提供可复现的代码、云资源体验流程、数据集或实验方案；</li><li>参与术语统一、技术审校、案例评审和内容翻译。</li></ul><p>贡献内容应尊重原创与授权边界；涉及企业数据、客户信息、内部系统和安全细节时，请先完成必要的脱敏与许可确认。</p><h2 id="_5-贡献者" tabindex="-1">5. 贡献者 <a class="header-anchor" href="#_5-贡献者" aria-label="Permalink to &quot;5. 贡献者&quot;">​</a></h2><p>感谢所有参与架构设计、章节写作、案例整理与内容审校的贡献者。</p><h3 id="阿里云" tabindex="-1">阿里云 <a class="header-anchor" href="#阿里云" aria-label="Permalink to &quot;阿里云&quot;">​</a></h3><table tabindex="0"><thead><tr><th>贡献领域</th><th>贡献者</th></tr></thead><tbody><tr><td>前言</td><td>麻芃</td></tr><tr><td>开发者调查报告</td><td>任娟、王晨</td></tr><tr><td>架构篇</td><td>王晨、刘军、沈林</td></tr><tr><td>构建篇</td><td>刘军、泮圣伟、王晨</td></tr><tr><td>运行篇</td><td>赵庆杰、李诗波、林清山、黄晓萌、张添翼、赵源筱、孙校、宋震、胡庆达、柳遵飞、朱桐、余华峰、罗鑫、孔可青</td></tr><tr><td>治理篇</td><td>肖长军、周洋、张磊、王方、张海彬、程书意、刘子明、饶子昊、任懿、杨永、王硕、马昕、刘宇轩、杨翊</td></tr><tr><td>调优篇</td><td>张寒萌、李盛荣、王亚宁、孙坚运、马云雷、王桢、郑前祎、刘航、陈新</td></tr><tr><td>实践篇</td><td>杨涛、朱颜、余艾琳、胡峻、姜剑、张添翼</td></tr><tr><td>总结与展望篇</td><td>林演</td></tr></tbody></table><h3 id="外部贡献者" tabindex="-1">外部贡献者 <a class="header-anchor" href="#外部贡献者" aria-label="Permalink to &quot;外部贡献者&quot;">​</a></h3><p>项目持续开放社区贡献，欢迎开发者、架构师、研究者、企业技术团队和产品实践者通过 Issue 或 Pull Request 参与内容共建；贡献被采纳后，贡献者信息将补充到本模块。</p><hr><p>如果这份白皮书可以帮助您更好地理解、构建、运行、治理和调优 Agent，欢迎分享、讨论并参与共建。</p>',41)])])}const p=a(n,[["render",o]]);export{b as __pageData,p as default};
